begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(35);
select set_config('test.surface_layout','{"body":{"x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1},"objects":[{"id":"00000000-0000-4000-8000-000000000093","name":"Bench","slug":"bench","x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"none","pulleyHeight":1.5}],"supports":[{"region":"left-hand","objectId":"00000000-0000-4000-8000-000000000093","surface":"pad","point":{"x":0,"y":0,"z":0.054},"normal":{"x":0,"y":0,"z":1},"turn":0}]}',true);
select ok(private.valid_studio_layout(current_setting('test.surface_layout')::jsonb),'valid part-local support');
select ok(private.valid_studio_layout(current_setting('test.surface_layout')::jsonb - 'supports'),'legacy layout preserved');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports}','[]')),'empty supports accepted');
select set_config('test.surface_floor',jsonb_set(jsonb_set(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,objectId}','null'),'{supports,0,surface}','"floor"'),'{supports,0,normal}','{"x":0,"y":1,"z":0}')::text,true);
select ok(private.valid_studio_layout(current_setting('test.surface_floor')::jsonb),'floor support accepted');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_floor')::jsonb,'{supports,0,point,y}','0.01')),'floating floor anchor rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_floor')::jsonb,'{supports,0,normal}','{"x":0,"y":-1,"z":0}')),'downward floor normal rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_floor')::jsonb,'{supports,0,normal}','{"x":1,"y":0,"z":0}')),'sideways floor normal rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports}',((current_setting('test.surface_layout')::jsonb)->'supports') || ((current_setting('test.surface_layout')::jsonb)->'supports'))),'duplicate region rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,region}','"head"')),'unknown region rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,objectId}','"00000000-0000-4000-8000-000000000099"')),'orphan rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,surface}','"floor"')),'bench floor mismatch rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,normal}','{"x":0,"y":0,"z":0}')),'nonunit normal rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,point,x}','11')),'point bounds enforced');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,turn}','181')),'turn bounds enforced');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,extra}','true')),'unknown fields rejected');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_layout')::jsonb,'{seating}','{"benchId":"00000000-0000-4000-8000-000000000093","facing":"front"}')),'legacy seating conflicts rejected');
select set_config('test.surface_weight','{"id":"00000000-0000-4000-8000-000000000094","name":"Weight","slug":"dumbbell","x":0,"y":0,"z":0,"rotationX":0,"rotationY":0,"rotationZ":0,"scale":1,"attachment":"left","pulleyHeight":1.5}',true);
select set_config('test.surface_held',jsonb_set(current_setting('test.surface_layout')::jsonb,'{objects}',(current_setting('test.surface_layout')::jsonb->'objects') || jsonb_build_array(current_setting('test.surface_weight')::jsonb))::text,true);
select ok(not private.valid_studio_layout(current_setting('test.surface_held')::jsonb),'held hand contact rejected');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_held')::jsonb,'{supports,0,region}','"left-elbow"')),'elbow support with held weight accepted');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_held')::jsonb,'{supports,0,region}','"left-forearm"')),'same side held hand and forearm support rejected');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_held')::jsonb,'{supports,0,region}','"right-forearm"')),'opposite side held hand and forearm support accepted');
select ok(not private.valid_studio_layout(jsonb_set(jsonb_set(current_setting('test.surface_held')::jsonb,'{supports,0,region}','"left-elbow"'),'{objects,1,elbowLocks}','{"left":{"x":0,"y":1,"z":0}}')),'duplicate elbow driver rejected');
select ok(not private.valid_studio_layout(jsonb_set(jsonb_set(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,objectId}','null'),'{supports,0,surface}','"floor"'),'{objects}',jsonb_build_array(jsonb_set(jsonb_set(current_setting('test.surface_weight')::jsonb,'{slug}','"leg-press"'),'{attachment}','"none"') || '{"machineUse":true}'::jsonb))),'active machine conflict rejected');
select set_config('test.surface_target',jsonb_set(jsonb_set(current_setting('test.surface_layout')::jsonb,'{supports,0,surface}','"body"'),'{objects}',jsonb_build_array(current_setting('test.surface_weight')::jsonb || '{"id":"00000000-0000-4000-8000-000000000093","attachment":"right"}'::jsonb))::text,true);
select ok(not private.valid_studio_layout(current_setting('test.surface_target')::jsonb),'held weight support target rejected');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_target')::jsonb,'{objects,0,attachment}','"none"')),'unheld weight support target accepted');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_target')::jsonb,'{objects,0,slug}','"cable-machine"')),'rigid cable frame support allowed');
select set_config('test.surface_cuff',jsonb_set(jsonb_set(jsonb_set(current_setting('test.surface_target')::jsonb,'{objects,0,slug}','"cable-machine"'),'{objects,0,attachment}','"left"'),'{objects,0,cableAttachment}','"cuff"')::text,true);
select ok(not private.valid_studio_layout(current_setting('test.surface_cuff')::jsonb),'default wrist cuff conflicts with hand support');
select ok(not private.valid_studio_layout(jsonb_set(current_setting('test.surface_cuff')::jsonb,'{objects,0,cuffPosition}','"wrist"')),'explicit wrist cuff conflicts with hand support');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_cuff')::jsonb,'{objects,0,cuffPosition}','"upper-arm"')),'upper-arm cuff leaves hand endpoint available');
select ok(private.valid_studio_layout(jsonb_set(current_setting('test.surface_cuff')::jsonb,'{supports,0,region}','"left-foot"')),'cuff does not claim foot endpoint');
insert into auth.users(id,email,aud,role) values
  ('00000000-0000-4000-8000-000000000095','surface-owner@example.test','authenticated','authenticated'),
  ('00000000-0000-4000-8000-000000000096','surface-other@example.test','authenticated','authenticated');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000095',true);
select set_config('test.surface_scene',jsonb_build_object('durationMs',3200,'cameraAngle','front','equipment',null,'keyframes','[{"timeMs":0,"poses":{}},{"timeMs":3200,"poses":{}}]'::jsonb,'studio',current_setting('test.surface_layout')::jsonb)::text,true);
select set_config('test.surface_private',public.create_workshop_exercise(current_setting('test.surface_scene')::jsonb)::text,true);
select is((select studio_layout from public.exercise_scenes where content_id=(select content_id from public.private_exercises where id=current_setting('test.surface_private')::uuid)),current_setting('test.surface_layout')::jsonb,'owner saves support values exactly');
select throws_ok($$select public.save_private_scene(current_setting('test.surface_private')::uuid,jsonb_set(current_setting('test.surface_scene')::jsonb,'{studio,supports,0,turn}','181'))$$,'23514',null,'invalid save rejected');
select is((select studio_layout from public.exercise_scenes where content_id=(select content_id from public.private_exercises where id=current_setting('test.surface_private')::uuid)),current_setting('test.surface_layout')::jsonb,'failed save preserves contacts');
select public.replace_private_share(current_setting('test.surface_private')::uuid,repeat('e',64));
reset role;
select set_config('test.surface_clone',private.clone_exercise_content((select content_id from public.private_exercises where id=current_setting('test.surface_private')::uuid),'submission_editorial',null)::text,true);
select is((select studio_layout from public.exercise_scenes where content_id=current_setting('test.surface_clone')::uuid),current_setting('test.surface_layout')::jsonb,'review snapshot preserves contacts');
set local role anon;
select is(public.read_shared_private_scene(repeat('e',64))->'studio',current_setting('test.surface_layout')::jsonb,'shared viewer receives contacts');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000096',true);
select throws_ok($$select public.save_private_scene(current_setting('test.surface_private')::uuid,current_setting('test.surface_scene')::jsonb)$$,'P0001','private exercise not found','other account cannot replace supports');
reset role;
select * from finish();
rollback;
